"use client";

import { useEffect, useRef, useState } from "react";

// 模型不返回思考流(reasoning_content)时的兜底氛围词
const PHRASES = [
  "读懂原文的语气和意图…",
  "盘几种不同的表达方向…",
  "对照韶音的腔调打磨措辞…",
  "检查有没有夸大或编造…",
  "整理成几个可选版本…",
];

const Dots = () => (
  <span className="flex gap-1">
    <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand [animation-delay:-0.3s]" />
    <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand [animation-delay:-0.15s]" />
    <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand" />
  </span>
);

export default function ThinkingIndicator({ thinking }: { thinking?: string }) {
  const hasReal = !!(thinking && thinking.trim());
  const [text, setText] = useState("");
  const [pi, setPi] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);

  // 兜底打字机:仅在没有真实思考流时运行
  useEffect(() => {
    if (hasReal) return;
    const phrase = PHRASES[pi % PHRASES.length];
    let i = 0;
    let timer: ReturnType<typeof setTimeout>;
    const typeNext = () => {
      if (i <= phrase.length) {
        setText(phrase.slice(0, i));
        i++;
        timer = setTimeout(typeNext, 50);
      } else {
        timer = setTimeout(() => setPi((p) => p + 1), 1200);
      }
    };
    typeNext();
    return () => clearTimeout(timer);
  }, [pi, hasReal]);

  // 真实思考流:新内容到来时自动滚到底部
  useEffect(() => {
    if (hasReal && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [thinking, hasReal]);

  if (hasReal) {
    return (
      <div className="rounded-xl border border-gray-100 bg-white/70 p-3">
        <div className="mb-1.5 flex items-center gap-2 text-xs text-ink-faint">
          <Dots />
          <span>模型正在思考</span>
        </div>
        <div
          ref={scrollRef}
          className="max-h-40 overflow-y-auto whitespace-pre-wrap text-xs leading-relaxed text-ink-soft"
        >
          {thinking}
          <span className="animate-pulse text-brand">▋</span>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2 text-sm text-ink-soft">
      <Dots />
      <span className="text-ink">
        {text}
        <span className="animate-pulse text-brand">▋</span>
      </span>
    </div>
  );
}

